create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,display_name text not null default 'MySocial User',bio text default '',avatar_url text default '',created_at timestamptz default now());
create table if not exists posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references profiles(id) on delete cascade,body text not null check(length(body)<=2200),media_url text default '',created_at timestamptz default now());
create table if not exists follows(follower_id uuid references profiles(id) on delete cascade,following_id uuid references profiles(id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists likes(user_id uuid references profiles(id) on delete cascade,post_id uuid references posts(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,post_id));
create table if not exists comments(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,post_id uuid references posts(id) on delete cascade,body text not null,created_at timestamptz default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid references profiles(id) on delete cascade,actor_id uuid references profiles(id) on delete cascade,type text not null,post_id uuid references posts(id) on delete cascade,read boolean default false,created_at timestamptz default now());
alter table profiles enable row level security;alter table posts enable row level security;alter table follows enable row level security;alter table likes enable row level security;alter table comments enable row level security;alter table notifications enable row level security;
create policy "profiles read" on profiles for select using(true);create policy "profile own insert" on profiles for insert with check(auth.uid()=id);create policy "profile own update" on profiles for update using(auth.uid()=id);
create policy "posts read" on posts for select using(true);create policy "posts own insert" on posts for insert with check(auth.uid()=author_id);create policy "posts own update" on posts for update using(auth.uid()=author_id);create policy "posts own delete" on posts for delete using(auth.uid()=author_id);
create policy "follows read" on follows for select using(true);create policy "follow insert" on follows for insert with check(auth.uid()=follower_id);create policy "follow delete" on follows for delete using(auth.uid()=follower_id);
create policy "likes read" on likes for select using(true);create policy "like insert" on likes for insert with check(auth.uid()=user_id);create policy "like delete" on likes for delete using(auth.uid()=user_id);
create policy "comments read" on comments for select using(true);create policy "comment insert" on comments for insert with check(auth.uid()=user_id);
create policy "notifications own" on notifications for select using(auth.uid()=recipient_id);
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,username,display_name) values(new.id,lower(regexp_replace(split_part(new.email,'@',1),'[^a-zA-Z0-9_]','','g'))||'_'||substr(new.id::text,1,6),coalesce(new.raw_user_meta_data->>'name','MySocial User'));return new;end;$$;
drop trigger if exists user_profile on auth.users;create trigger user_profile after insert on auth.users for each row execute procedure public.new_profile();